"""Migration of the Meridian CRM 4.2 nightly case-escalation job."""

from datetime import datetime


def _datediff(date1: object, date2: object) -> int:
    """Return whole calendar days date1 minus date2 under legacy semantics."""
    first = "" if date1 is None else str(date1)
    second = "" if date2 is None else str(date2)

    if not first or not second or first == "00000000" or second == "00000000":
        return 0

    return (
        datetime.strptime(first, "%Y%m%d").date()
        - datetime.strptime(second, "%Y%m%d").date()
    ).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation workflow events in legacy primary-key order."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: str(row.get("CASE_ID", ""))):
        if case.get("DEL_FLG", "") == "Y":
            continue

        status = case.get("STAT_CD", "")
        age_days = _datediff(today, case.get("OPEN_DT", ""))

        if status == "N" and age_days >= 2:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

        if (
            status == "A"
            and case.get("ESC_FLG", "") != "Y"
            and age_days >= 7
        ):
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

    return events
